import sys
import os
import json

def normalize_date(val):
    """Convert YYYYMMDD to YYYY-MM-DD. If already formatted, return as is."""
    if isinstance(val, str):
        if len(val) == 8 and val.isdigit():
            return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    return val

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Mapping from rule_id and fact_name to (document_name, field_name)
    rule_map = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "classification date": ("fda_enforcement_reports", "center_classification_date"),
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "termination date": ("fda_enforcement_reports", "termination_date"),
        }
    }

    # Index records by document and recall_number
    doc_index = {}  # doc_name -> {recall_number: [record, ...]}
    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            doc_name = filename[:-5]
            filepath = os.path.join(packet_dir, filename)
            try:
                with open(filepath) as f:
                    data = json.load(f)
            except (json.JSONDecodeError, IOError):
                continue
            records = []
            if isinstance(data, dict) and 'results' in data:
                records = data['results']
            elif isinstance(data, list):
                records = data
            else:
                continue
            for record in records:
                if not isinstance(record, dict):
                    continue
                recall_number = record.get('recall_number')
                if recall_number:
                    doc_index.setdefault(doc_name, {}).setdefault(recall_number, []).append(record)

    output = {}
    for pair in manifest.get("pairs", []):
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])
        result_obj = {}
        for fact_name in facts:
            if rule_id in rule_map and fact_name in rule_map[rule_id]:
                doc_name, field_name = rule_map[rule_id][fact_name]
                records = doc_index.get(doc_name, {}).get(entity, [])
                values = set()
                for record in records:
                    val = record.get(field_name)
                    if val is not None:
                        if not isinstance(val, str):
                            val = str(val)
                        else:
                            val = val.strip()
                        if val != "":
                            if field_name in ("recall_initiation_date", "center_classification_date", "termination_date"):
                                val = normalize_date(val)
                            values.add(val)
                if len(values) == 0:
                    result_obj[fact_name] = "ABSENT"
                elif len(values) == 1:
                    result_obj[fact_name] = [next(iter(values)), doc_name]
                else:
                    result_obj[fact_name] = "CONFLICT"
            else:
                result_obj[fact_name] = "ABSENT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
