Looking at this problem, I need to:
1. Parse the FDA enforcement reports JSON file
2. For each pair in the manifest, extract the relevant facts based on the rule
3. Convert dates from YYYYMMDD format to YYYY-MM-DD
4. Handle ABSENT (empty/missing values) and CONFLICT (disagreeing values across records)

```python
import json
import os
import sys

def convert_date(date_str):
    """Convert YYYYMMDD to YYYY-MM-DD"""
    if not date_str or len(date_str) != 8 or not date_str.isdigit():
        return None
    return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load the FDA enforcement reports
    fda_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(fda_path) as f:
        fda_data = json.load(f)

    # Build a map from recall_number to list of reports
    reports_by_recall = {}
    for report in fda_data.get("results", []):
        recall_number = report.get("recall_number", "")
        if recall_number not in reports_by_recall:
            reports_by_recall[recall_number] = []
        reports_by_recall[recall_number].append(report)

    # Define field mappings for each rule's facts
    fact_fields = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date",
        },
