import sys
import os
import json
from datetime import datetime

# Mapping from (rule_id, fact_name) to (document, field, type)
# document is the file name without extension
# type is used for formatting: "date" -> YYYY-MM-DD, "string" -> as-is
FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date", "date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "termination date": ("fda_enforcement_reports", "termination_date", "date"),
    },
}


def format_value(value, value_type):
    """Format a raw string value according to its type."""
    if value_type == "date":
        s = value.strip()
        if not s:
            return None
        # Try YYYYMMDD
        try:
            dt = datetime.strptime(s, "%Y%m%d")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
        # Try YYYY-MM-DD (already formatted)
        try:
            datetime.strptime(s, "%Y-%m-%d")
            return s
        except ValueError:
            pass
        # If it doesn't match expected date formats, return the raw string
        return s
    else:
        # For non-date types, return the stripped string if non-empty
        s = value.strip()
        return s if s else None


def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Load the FDA enforcement reports file
    doc_name = "fda_enforcement_reports"
    doc_file = os.path.join(packet_dir, doc_name + ".json")
    records = []
    if os.path.exists(doc_file):
        with open(doc_file, "r", encoding="utf-8") as f:
            data = json.load(f)
        records = data.get("results", [])

    # Group records by recall_number
    records_by_recall = {}
    for rec in records:
        recall = rec.get("recall_number")
        if recall:
            records_by_recall.setdefault(recall, []).append(rec)

    result = {}
    for pair in pairs:
        if "::" not in pair:
            result[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        pair_result = {}

        for fact_name in fact_names:
            # Look up the document, field, and type for this fact
            if rule_id in FACT_MAP and fact_name in FACT_MAP[rule_id]:
                doc, field, vtype = FACT_MAP[rule_id][fact_name]
            else:
                pair_result[fact_name] = "ABSENT"
                continue

            # Find all records for this entity (recall_number)
            recs = records_by_recall.get(entity, [])
            if not recs:
                pair_result[fact_name] = "ABSENT"
                continue

            # Collect non-empty formatted values
            values = []
            for rec in recs:
                raw = rec.get(field, "")
                if raw is None:
                    raw = ""
                formatted = format_value(str(raw), vtype)
                if formatted is not None:
                    values.append(formatted)

            # Determine the result based on distinct values
            distinct_values = list(dict.fromkeys(values))  # preserve order, remove duplicates
            if len(distinct_values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(distinct_values) == 1:
                pair_result[fact_name] = [distinct_values[0], doc]
            else:
                pair_result[fact_name] = "CONFLICT"

        result[pair] = pair_result

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
