    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    fact_fields = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date",
    }

    records = []
    for path in sorted(glob.glob(os.path.join(packet_dir, "*.json"))):
        with open(path) as f:
            data = json.load(f)
        if "results" not in data:
            continue
        doc_name = os.path.splitext(os.path.basename(path))[0]
        for r in data["results"]:
            records.append((r, doc_name))

    by_recall = {}
    for r, doc in records:
        rn = r.get("recall_number", "")
        if rn:
            by_recall.setdefault(rn, []).append((r, doc))

    result = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])

        matching = by_recall.get(entity, [])

        pair_result = {}
        for fact_name in fact_names:
            field = fact_fields.get(fact_name)
            if field is None:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for r, doc in matching:
                raw = r.get(field, "")
                if raw is None:
                    raw = ""
                parsed = parse_date(raw)
                if parsed is not None:
                    values.append((parsed, doc))

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                unique_values = set(v[0] for v in values)
                if len(unique_values) > 1:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [values[0][0], values[0][1]]

        result[pair] = pair_result

    print(json.dumps(result, indent=2))

